<script>
 import ControlledSend from './ControlledSend.svelte';
 import EmailStudioPanel from './EmailStudioPanel.svelte';
 export let panel;export let host;
 const supported=name=>typeof host.emailRequest==='function'&&Array.isArray(host.emailCapabilities)&&host.emailCapabilities.includes(name);
 let preview=null,review=null,approved=null,confirmed=false,busy=false,error='',notice='',mobile=false,plain=false,epoch=0;
 $: if(panel.draft||preview&&preview.revision!==panel.revision||review&&review.revision!==panel.revision){preview=null;review=null;approved=null;confirmed=false;epoch++;}
 async function action(name){if(!supported(name)){error='This email action is unavailable.';return;}if(busy)return;if(panel.draft){error='Save your changes before continuing.';return;}const revision=panel.revision,version=++epoch;busy=true;error='';try{const value=await host.emailRequest(panel.ref.id,name,{expectedRevision:revision,...(name==='approve'?{review}: {})});if(version!==epoch||panel.abort.signal.aborted)return;if(name==='preview')preview=value;if(name==='review'){const rendered=await host.emailRequest(panel.ref.id,'preview',{expectedRevision:revision});if(version!==epoch||panel.abort.signal.aborted)return;review=value;confirmed=false;approved=null;preview={...value,previewHtml:rendered.previewHtml};}if(name==='approve'){approved=value;notice='Approval recorded for this exact version. No email was sent.';}}catch(e){error=e.message;}finally{busy=false;}}
</script>
<EmailStudioPanel {panel} {host}/>
{#if supported('preview')||supported('review')}<section aria-label="Preview and human review" class="review">
 <h2>Preview and review</h2><p>Preview saved content, then approve the exact recipients, sender, attachments and version.</p>
 <div class="toolbar">{#if supported('preview')}<button disabled={busy||!!panel.draft} on:click={()=>action('preview')}>Preview saved email</button>{/if}{#if supported('review')&&supported('preview')}<button disabled={busy||!!panel.draft} on:click={()=>action('review')}>Review exact version</button>{/if}{#if preview}<button aria-pressed={mobile} on:click={()=>mobile=!mobile}>{mobile?'Desktop preview':'Mobile preview'}</button><button aria-pressed={plain} on:click={()=>plain=!plain}>Plain text</button>{/if}</div>
 {#if preview}{#if plain}<pre class="plain" aria-label="Plain-text email">{preview.text}</pre>{:else}<iframe class:mobile title="Saved email preview" sandbox="" srcdoc={preview.previewHtml}></iframe>{/if}{/if}
 {#if review}<div class="summary"><h3>Review version {review.revision}</h3><dl><dt>From</dt><dd>{review.identity.name} &lt;{review.identity.address}&gt;</dd><dt>To</dt><dd>{review.document.to.join(', ')}</dd><dt>Cc</dt><dd>{review.document.cc.join(', ')||'None'}</dd><dt>Bcc</dt><dd>{review.document.bcc.join(', ')||'None'}</dd><dt>Subject</dt><dd>{review.document.subject}</dd><dt>Attachments and images</dt><dd><ul>{#each review.bound as asset}<li>{asset.filename} · <small>SHA-256 {asset.sha256}</small></li>{/each}</ul></dd></dl><p class="digest">Approval fingerprint: {review.digest}</p>{#if supported('approve')}<label class="confirm"><input type="checkbox" bind:checked={confirmed} disabled={busy||!!approved}/> I approve the displayed saved content, exact sender, recipients and attachments for version {review.revision}.</label><button disabled={!confirmed||busy||!!approved||!!panel.draft} on:click={()=>action('approve')}>Approve exact version</button>{/if}</div>{/if}
 {#if approved}<p role="status">Approved version {approved.revision}. Editing creates a new version and invalidates this approval.</p>{/if}{#if error}<p role="alert">{error}</p>{/if}<p role="status" aria-live="polite">{notice}</p>
</section>{/if}
<ControlledSend {panel} {host} approval={approved}/>
<style>.review{margin-top:2rem;border-top:1px solid #d1d5db;padding-top:1rem}h2{font-size:1rem}p,dd,dt,label,button{font-size:.875rem}button{font:inherit;border:1px solid #cbd5e1;border-radius:.75rem;background:#fff;color:#111827;padding:.6rem .85rem;cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible{outline:2px solid #475569;outline-offset:3px}.toolbar{display:flex;gap:.5rem;flex-wrap:wrap;margin:1rem 0}iframe{display:block;width:100%;max-width:680px;height:680px;border:1px solid #e5e7eb;border-radius:.75rem;background:#fff}.mobile{max-width:375px}.plain{white-space:pre-wrap;background:#f3f4f6;padding:1rem;line-height:1.6}.summary{padding:1rem;border:1px solid #d1d5db;border-radius:1rem;margin-top:1rem}dt{font-weight:600;margin-top:.7rem}dd{margin:.2rem 0;overflow-wrap:anywhere}.digest,small{font-size:.7rem;overflow-wrap:anywhere}.confirm{display:flex;align-items:flex-start;gap:.5rem;line-height:1.5;margin:1rem 0}[role=alert]{color:#b91c1c}</style>
